  1→//! Workflow execution orchestration.
  2→
  3→use std::collections::{HashMap, HashSet};
  4→use std::path::Path;
  5→use std::time::{Duration, Instant};
  6→
  7→use tracing::warn;
  8→
  9→use crate::config::interpolation::InterpolationContext;
 10→use crate::config::schema::StepOverride;
 11→use crate::config::BivvyConfig;
 12→use crate::error::{BivvyError, Result};
 13→use crate::requirements::checker::GapChecker;
 14→use crate::requirements::installer;
 15→use crate::shell::OutputLine;
 16→use crate::steps::{
 17→    execute_step, run_check, ExecutionOptions, ResolvedStep, StepResult, StepStatus,
 18→};
 19→use crate::ui::spinner::live_output_callback;
 20→use crate::ui::theme::BivvyTheme;
 21→use crate::ui::{
 22→    format_duration, OutputMode, Prompt, PromptOption, PromptType, StatusKind, UserInterface,
 23→};
 24→
 25→use super::dependency::{DependencyGraph, SkipBehavior};
 26→use super::patterns::{self, StepContext};
 27→use super::recovery::{self, RecoveryAction};
 28→
 29→/// Maximum total execution attempts per step (auto-retries + manual retries).
 30→/// Prevents infinite loops when the recovery prompt always returns "retry"
 31→/// (e.g., in test environments with MockUI).
 32→const MAX_STEP_ATTEMPTS: u32 = 100;
 33→
 34→/// Progress events emitted during workflow execution.
 35→#[derive(Debug)]
 36→pub enum RunProgress<'a> {
 37→    /// A step is about to start.
 38→    StepStarting {
 39→        name: &'a str,
 40→        index: usize,
 41→        total: usize,
 42→    },
 43→    /// A step finished.
 44→    StepFinished {
 45→        name: &'a str,
 46→        result: &'a StepResult,
 47→    },
 48→    /// A step was skipped.
 49→    StepSkipped { name: &'a str },
 50→}
 51→
 52→/// Orchestrates the execution of a workflow.
 53→pub struct WorkflowRunner<'a> {
 54→    config: &'a BivvyConfig,
 55→    steps: HashMap<String, ResolvedStep>,
 56→}
 57→
 58→/// Result of running a workflow.
 59→#[derive(Debug)]
 60→pub struct WorkflowResult {
 61→    /// Workflow name.
 62→    pub workflow: String,
 63→    /// Results from each executed step.
 64→    pub steps: Vec<StepResult>,
 65→    /// Names of skipped steps.
 66→    pub skipped: Vec<String>,
 67→    /// Total duration.
 68→    pub duration: Duration,
 69→    /// Whether all steps succeeded.
 70→    pub success: bool,
 71→    /// Whether the workflow was aborted by the user during recovery.
 72→    pub aborted: bool,
 73→}
 74→
 75→/// Options for running a workflow.
 76→#[derive(Debug, Default)]
 77→pub struct RunOptions {
 78→    /// Workflow name (defaults to "default").
 79→    pub workflow: Option<String>,
 80→    /// Only run these steps.
 81→    pub only: HashSet<String>,
 82→    /// Skip these steps.
 83→    pub skip: HashSet<String>,
 84→    /// How to handle skipped step dependencies.
 85→    pub skip_behavior: SkipBehavior,
 86→    /// Force re-run these steps even if complete.
 87→    pub force: HashSet<String>,
 88→    /// Dry run mode.
 89→    pub dry_run: bool,
 90→    /// Requirements that are provided by the environment and should skip gap checks.
 91→    pub provided_requirements: HashSet<String>,
 92→    /// Active environment name for only_environments filtering.
 93→    pub active_environment: Option<String>,
 94→}
 95→
 96→impl<'a> WorkflowRunner<'a> {
 97→    /// Create a new workflow runner.
 98→    pub fn new(config: &'a BivvyConfig, steps: HashMap<String, ResolvedStep>) -> Self {
 99→        Self { config, steps }
100→    }
101→
102→    /// Run the specified workflow.
103→    pub fn run(
104→        &self,
105→        options: &RunOptions,
106→        context: &InterpolationContext,
107→        global_env: &HashMap<String, String>,
108→        project_root: &Path,
109→    ) -> Result<WorkflowResult> {
110→        self.run_with_progress(options, context, global_env, project_root, None, |_| {})
111→    }
112→
113→    /// Run the specified workflow with a progress callback.
114→    pub fn run_with_progress(
115→        &self,
116→        options: &RunOptions,
117→        context: &InterpolationContext,
118→        global_env: &HashMap<String, String>,
119→        project_root: &Path,
120→        mut gap_checker: Option<&mut GapChecker<'_>>,
121→        mut on_progress: impl FnMut(RunProgress<'_>),
122→    ) -> Result<WorkflowResult> {
123→        let start = Instant::now();
124→        let workflow_name = options.workflow.as_deref().unwrap_or("default");
125→
126→        // Build dependency graph
127→        let graph = self.build_graph(workflow_name)?;
128→
129→        // Compute skips
130→        let skipped = graph.compute_skips(&options.skip, options.skip_behavior);
131→
132→        // Get execution order
133→        let order = graph.topological_order()?;
134→
135→        // Filter by only_environments and --only/--skip
136→        let mut env_skipped: Vec<String> = Vec::new();
137→        let steps_to_run: Vec<_> = order
138→            .iter()
139→            .filter(|s| !skipped.contains(*s))
140→            .filter(|s| options.only.is_empty() || options.only.contains(*s))
141→            .filter(|s| {
142→                if let Some(step) = self.steps.get(*s) {
143→                    if !step.only_environments.is_empty() {
144→                        if let Some(ref active_env) = options.active_environment {
145→                            if !step.only_environments.iter().any(|e| e == active_env) {
146→                                env_skipped.push(s.to_string());
147→                                return false;
148→                            }
149→                        }
150→                    }

  1→//! Output mode and writer.
  2→
  3→use std::io::Write;
  4→use std::str::FromStr;
  5→
  6→/// Output verbosity mode.
  7→#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
  8→pub enum OutputMode {
  9→    /// Show all output including command output.
 10→    Verbose,
 11→    /// Show progress and status only.
 12→    #[default]
 13→    Normal,
 14→    /// Show minimal output (spinners + final status).
 15→    Quiet,
 16→    /// Show nothing except errors.
 17→    Silent,
 18→}
 19→
 20→impl FromStr for OutputMode {
 21→    type Err = String;
 22→
 23→    fn from_str(s: &str) -> Result<Self, Self::Err> {
 24→        match s.to_lowercase().as_str() {
 25→            "verbose" => Ok(Self::Verbose),
 26→            "normal" => Ok(Self::Normal),
 27→            "quiet" => Ok(Self::Quiet),
 28→            "silent" => Ok(Self::Silent),
 29→            _ => Err(format!("unknown output mode: {}", s)),
 30→        }
 31→    }
 32→}
 33→
 34→impl From<crate::config::schema::OutputMode> for OutputMode {
 35→    fn from(config_mode: crate::config::schema::OutputMode) -> Self {
 36→        match config_mode {
 37→            crate::config::schema::OutputMode::Verbose => Self::Verbose,
 38→            crate::config::schema::OutputMode::Quiet => Self::Quiet,
 39→            crate::config::schema::OutputMode::Silent => Self::Silent,
 40→        }
 41→    }
 42→}
 43→
 44→impl OutputMode {
 45→    /// Check if this mode shows command output.
 46→    pub fn shows_command_output(&self) -> bool {
 47→        matches!(self, Self::Verbose)
 48→    }
 49→
 50→    /// Check if this mode shows progress spinners.
 51→    pub fn shows_spinners(&self) -> bool {
 52→        matches!(self, Self::Verbose | Self::Normal | Self::Quiet)
 53→    }
 54→
 55→    /// Check if this mode shows status messages.
 56→    pub fn shows_status(&self) -> bool {
 57→        !matches!(self, Self::Silent)
 58→    }
 59→}
 60→
 61→/// Output writer that respects output mode.
 62→#[derive(Debug)]
 63→pub struct Output {
 64→    mode: OutputMode,
 65→}
 66→
 67→impl Output {
 68→    /// Create a new output writer.
 69→    pub fn new(mode: OutputMode) -> Self {
 70→        Self { mode }
 71→    }
 72→
 73→    /// Get the output mode.
 74→    pub fn mode(&self) -> OutputMode {
 75→        self.mode
 76→    }
 77→
 78→    /// Write a line if the mode allows status messages.
 79→    pub fn println(&self, msg: &str) {
 80→        if self.mode.shows_status() {
 81→            println!("{}", msg);
 82→        }
 83→    }
 84→
 85→    /// Write command output if verbose mode.
 86→    pub fn command_output(&self, output: &str) {
 87→        if self.mode.shows_command_output() {
 88→            print!("{}", output);
 89→            let _ = std::io::stdout().flush();
 90→        }
 91→    }
 92→}
