 46→    }
 47→
 48→    /// Build run options from args.
 49→    fn build_options(&self) -> RunOptions {
 50→        let skip_behavior = match self.args.skip_behavior.as_str() {
 51→            "skip_only" => SkipBehavior::SkipOnly,
 52→            "run_anyway" => SkipBehavior::RunAnyway,
 53→            _ => SkipBehavior::SkipWithDependents,
 54→        };
 55→
 56→        RunOptions {
 57→            workflow: Some(self.args.workflow.clone()),
 58→            only: self.args.only.iter().cloned().collect(),
 59→            skip: self.args.skip.iter().cloned().collect(),
 60→            skip_behavior,
 61→            force: self.args.force.iter().cloned().collect(),
 62→            dry_run: self.args.dry_run,
 63→            provided_requirements: HashSet::new(),
 64→            active_environment: None,
 65→        }
 66→    }
 67→
 68→    /// Resolve the target environment using the priority chain.
 69→    fn resolve_environment(&self, config: &crate::config::BivvyConfig) -> ResolvedEnvironment {
 70→        ResolvedEnvironment::resolve_from_config(self.args.env.as_deref(), &config.settings)
 71→    }
 72→
 73→    /// Resolve steps from configuration.
 74→    ///
 75→    /// Steps with a `template` field are resolved through the Registry,
 76→    /// which merges template defaults with config overrides. Steps without
 77→    /// a template are treated as inline definitions.
 78→    fn resolve_steps(
 79→        &self,
 80→        config: &crate::config::BivvyConfig,
 81→        environment: Option<&str>,
 82→    ) -> Result<HashMap<String, ResolvedStep>> {
 83→        let registry = if config.template_sources.is_empty() {
 84→            Registry::new(Some(&self.project_root))?
 85→        } else {
 86→            Registry::with_remote_sources(Some(&self.project_root), &config.template_sources)?
 87→        };
 88→
 89→        let mut steps = HashMap::new();
 90→        for (name, step_config) in &config.steps {
 91→            let resolved = if let Some(template_name) = &step_config.template {
 92→                let (template, _source) = registry.resolve(template_name)?;
 93→                ResolvedStep::from_template(
 94→                    name,
 95→                    template,
 96→                    step_config,
 97→                    &step_config.inputs,
 98→                    environment,
 99→                )
100→            } else {
101→                ResolvedStep::from_config(name, step_config, environment)
102→            };
103→            steps.insert(name.clone(), resolved);
104→        }
105→        Ok(steps)
106→    }
107→}
108→
109→impl Command for RunCommand {
110→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
111→        // Load configuration
112→        let config = match load_merged_config(&self.project_root) {
113→            Ok(c) => c,
114→            Err(BivvyError::ConfigNotFound { .. }) => {
115→                ui.error("No configuration found. Run 'bivvy init' first.");
116→                return Ok(CommandResult::failure(2));
117→            }
118→            Err(e) => return Err(e),
119→        };
120→
121→        // Deprecation warning for --ci flag
122→        if self.args.ci {
123→            ui.warning(
124→                "--ci is deprecated and will be removed in 2.0. \
125→                 Use --non-interactive and --env ci instead.",
126→            );
127→        }
128→
129→        // Apply config default_output when no CLI flag was explicitly set.
130→        // OutputMode::Normal means the user didn't pass --verbose or --quiet.
131→        if ui.output_mode() == OutputMode::Normal {
132→            ui.set_output_mode(config.settings.default_output.into());
133→        }
134→
135→        // Resolve environment (before header so we can use resolved workflow)
136→        let resolved_env = self.resolve_environment(&config);
137→        let env_name = resolved_env.name.clone();
138→
139→        // Warn if the environment is not known
140→        if !resolved_env.is_known(&config) {
141→            ui.warning(&format!(
142→                "Unknown environment '{}'. It is not defined in settings.environments                  or a built-in. Step overrides for this environment will have no effect.",
143→                env_name
144→            ));
145→        }
146→
147→        // Get provided_requirements from environment config
148→        let provided_requirements: HashSet<String> = config
149→            .settings
150→            .environments

  1→//! Command dispatching.
  2→//!
  3→//! This module provides the core command infrastructure:
  4→//! - [`Command`] trait for implementing commands
  5→//! - [`CommandResult`] for uniform result reporting
  6→//! - [`CommandDispatcher`] for routing CLI subcommands
  7→
  8→use std::path::{Path, PathBuf};
  9→
 10→use crate::cli::args::{Cli, Commands};
 11→use crate::error::Result;
 12→use crate::ui::UserInterface;
 13→
 14→/// Trait for command implementations.
 15→///
 16→/// Each CLI subcommand implements this trait to provide its execution logic.
 17→pub trait Command {
 18→    /// Execute the command.
 19→    ///
 20→    /// # Arguments
 21→    ///
 22→    /// * `ui` - User interface for displaying output and prompts
 23→    ///
 24→    /// # Returns
 25→    ///
 26→    /// A [`CommandResult`] indicating success/failure and exit code.
 27→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult>;
 28→}
 29→
 30→/// Result of command execution.
 31→#[derive(Debug)]
 32→pub struct CommandResult {
 33→    /// Whether the command succeeded.
 34→    pub success: bool,
 35→
 36→    /// Exit code to use (0 for success, non-zero for failure).
 37→    pub exit_code: i32,
 38→}
 39→
 40→impl CommandResult {
 41→    /// Create a successful result.
 42→    pub fn success() -> Self {
 43→        Self {
 44→            success: true,
 45→            exit_code: 0,
 46→        }
 47→    }
 48→
 49→    /// Create a failure result.
 50→    pub fn failure(exit_code: i32) -> Self {
 51→        Self {
 52→            success: false,
 53→            exit_code,
 54→        }
 55→    }
 56→}
 57→
 58→/// Dispatches CLI commands to their implementations.
 59→pub struct CommandDispatcher {
 60→    project_root: PathBuf,
 61→}
 62→
 63→impl CommandDispatcher {
 64→    /// Create a new dispatcher for the given project root.
 65→    pub fn new(project_root: PathBuf) -> Self {
 66→        Self { project_root }
 67→    }
 68→
 69→    /// Get the project root path.
 70→    pub fn project_root(&self) -> &Path {
 71→        &self.project_root
 72→    }
 73→
 74→    /// Dispatch and execute a command.
 75→    ///
 76→    /// Routes the CLI subcommand to the appropriate command implementation
 77→    /// and executes it.
 78→    pub fn dispatch(&self, cli: &Cli, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 79→        match &cli.command {
 80→            Some(Commands::Run(args)) => {
 81→                let cmd = super::run::RunCommand::new(&self.project_root, args.clone());
 82→                cmd.execute(ui)
 83→            }
 84→            Some(Commands::Init(args)) => {
 85→                let cmd = super::init::InitCommand::new(&self.project_root, args.clone());
 86→                cmd.execute(ui)
 87→            }
 88→            Some(Commands::Status(args)) => {
 89→                let cmd = super::status::StatusCommand::new(&self.project_root, args.clone());
 90→                cmd.execute(ui)
 91→            }
 92→            Some(Commands::List(args)) => {
 93→                let cmd = super::list::ListCommand::new(&self.project_root, args.clone());
 94→                cmd.execute(ui)
 95→            }
 96→            Some(Commands::Last(args)) => {
 97→                let cmd = super::last::LastCommand::new(&self.project_root, args.clone());
 98→                cmd.execute(ui)
 99→            }
100→            Some(Commands::History(args)) => {
101→                let cmd = super::history::HistoryCommand::new(&self.project_root, args.clone());
102→                cmd.execute(ui)
103→            }
104→            Some(Commands::Lint(args)) => {
105→                let cmd = super::lint::LintCommand::new(&self.project_root, args.clone());
106→                cmd.execute(ui)
107→            }
108→            Some(Commands::Config(args)) => {
109→                let cmd = super::config::ConfigCommand::new(&self.project_root, args.clone());
110→                cmd.execute(ui)
111→            }
112→            Some(Commands::Cache(args)) => {
113→                let cmd = super::cache::CacheCommand::new(args.clone());
114→                cmd.execute(ui)
115→            }
116→            Some(Commands::Feedback(args)) => {
117→                let cmd = super::feedback::FeedbackCommand::new(args.clone());
118→                cmd.execute(ui)
119→            }
120→            Some(Commands::Completions(args)) => {
121→                let cmd = super::completions::CompletionsCommand::new(args.clone());
122→                cmd.execute(ui)
123→            }
124→            None => {
125→                // Default to run command with default args
126→                let cmd = super::run::RunCommand::new(
127→                    &self.project_root,
128→                    crate::cli::args::RunArgs::default(),
129→                );
130→                cmd.execute(ui)
131→            }
132→        }
133→    }
134→}
